package gen

import (
	"encoding/json"

	"github.com/go-theft-craft/server/pkg/world"
)

// DefaultName is the registered name of the noise generator.
const DefaultName = "default"

// DefaultVersion is this generator's version. Bump it when a change moves
// terrain, so a world generated by an older build says so in its metadata.
const DefaultVersion = 1

// DefaultParams configures the noise generator.
//
// Every value here was a constant before M11.4, and DefaultDefaults
// transcribes them exactly: the golden chunk table is unchanged, which is the
// whole claim that the promotion changed nothing.
type DefaultParams struct {
	SeaLevel int `json:"sea_level"`
	// TerrainScale and DetailScale are the divisors the two height noise
	// fields sample at: larger is smoother.
	TerrainScale float64 `json:"terrain_scale"`
	DetailScale  float64 `json:"detail_scale"`
	// DetailAmplitude is how much the small-scale field moves the height.
	DetailAmplitude float64 `json:"detail_amplitude"`
	// MinHeight and MaxHeight clamp the result.
	MinHeight int `json:"min_height"`
	MaxHeight int `json:"max_height"`
	// BedrockDepth is how many layers above y=0 are randomised between
	// bedrock and stone.
	BedrockDepth int `json:"bedrock_depth"`

	Surface SurfaceParams `json:"surface"`
	Caves   CaveParams    `json:"caves"`
	Ores    []OreParams   `json:"ores"`
	Trees   TreeParams    `json:"trees"`
	Biomes  BiomeParams   `json:"biomes"`
}

// Type implements Params.
func (DefaultParams) Type() string { return DefaultName }

// SurfaceParams names the blocks the surface pass places and how deep it goes.
type SurfaceParams struct {
	Top        string `json:"top"`
	Filler     string `json:"filler"`
	Underwater string `json:"underwater"`
	Sand       string `json:"sand"`
	Sandstone  string `json:"sandstone"`
	Gravel     string `json:"gravel"`
	Stone      string `json:"stone"`
	// Depth is how many blocks of surface material sit under the top one, and
	// DesertDepth is the deeper sand a desert gets.
	Depth       int `json:"depth"`
	DesertDepth int `json:"desert_depth"`
	// BareStoneAbove is the height above which a mountain loses its grass.
	BareStoneAbove int `json:"bare_stone_above"`
}

// CaveParams configures the two noise fields that carve caves.
type CaveParams struct {
	Threshold float64 `json:"threshold"`
	LavaLevel int     `json:"lava_level"`
	// MinY is the lowest carved block and SurfaceMargin is how far below the
	// terrain top carving stops, so a cave never opens the surface.
	MinY          int     `json:"min_y"`
	SurfaceMargin int     `json:"surface_margin"`
	ScaleAXZ      float64 `json:"scale_a_xz"`
	ScaleAY       float64 `json:"scale_a_y"`
	ScaleBXZ      float64 `json:"scale_b_xz"`
	ScaleBY       float64 `json:"scale_b_y"`
}

// OreParams is one ore's placement rule.
type OreParams struct {
	Block    string `json:"block"`
	MinY     int    `json:"min_y"`
	MaxY     int    `json:"max_y"`
	VeinSize int    `json:"vein_size"`
	Attempts int    `json:"attempts"`
}

// TreeParams configures the decoration pass.
type TreeParams struct {
	// Density is trees per chunk, by canonical biome name.
	Density map[string]int `json:"density"`
	// DefaultDensity is what a biome not in Density gets.
	DefaultDensity int `json:"default_density"`
	// VegetationAttempts is how many positions the grass-and-flowers pass
	// tries per chunk.
	VegetationAttempts int `json:"vegetation_attempts"`
}

// BiomeParams configures biome selection and each biome's terrain shape.
type BiomeParams struct {
	TemperatureScale float64 `json:"temperature_scale"`
	RainfallScale    float64 `json:"rainfall_scale"`
	// OceanBelow and BeachBelow are how far under sea level the coarse height
	// field has to fall for a position to be ocean or beach.
	OceanBelow float64 `json:"ocean_below"`
	BeachBelow float64 `json:"beach_below"`
	// Terrain is each biome's height shape, by canonical name.
	Terrain map[string]BiomeTerrain `json:"terrain"`
	// DefaultTerrain is what a biome not in Terrain gets.
	DefaultTerrain BiomeTerrain `json:"default_terrain"`
}

// BiomeTerrain is one biome's height shape.
type BiomeTerrain struct {
	Amplitude float64 `json:"amplitude"`
	// BaseOffset is the biome's base height relative to sea level, so moving
	// sea level moves the land with it.
	BaseOffset float64 `json:"base_offset"`
}

