// defaultFactory registers the noise generator.
type defaultFactory struct{}

func (defaultFactory) Name() string     { return DefaultName }
func (defaultFactory) Version() int     { return DefaultVersion }
func (defaultFactory) Defaults() Params { return DefaultDefaults() }

func (defaultFactory) Parse(raw json.RawMessage) (Params, error) {
	p := DefaultDefaults()
	if err := parseParams(raw, &p); err != nil {
		return nil, err
	}

	return p, nil
}

func (defaultFactory) New(seed int64, p Params, reg world.StateRegistry) (Generator, error) {
	params, ok := p.(DefaultParams)
	if !ok {
		if p == nil {
			params = DefaultDefaults()
		} else {
			return nil, invalidParams(DefaultName, p)
		}
	}

	return NewDefaultGeneratorWith(seed, params, reg)
}

// invalidParams reports parameters of the wrong concrete type.
func invalidParams(name string, p Params) error {
	return &ParamsTypeError{Generator: name, Got: p.Type()}
}

// ParamsTypeError reports parameters handed to the wrong generator.
type ParamsTypeError struct {
	Generator string
	Got       string
}

func (e *ParamsTypeError) Error() string {
	return "gen: generator " + e.Generator + " was given " + e.Got + " parameters"
}
